const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1100,height:1200}});const results=[];for(const layout of ['original','balanced','classic','oval'])for(const [width,height]of [[440,782],[375,500],[320,400]]){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin:'style1',scene:'figma',layout,width,height}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});results.push({layout,width,height,...await p.evaluate(()=>{const r=document.querySelector('.mx-table').getBoundingClientRect(),v=document.querySelector('.mx-viewport').getBoundingClientRect(),n=document.querySelector('.mx-navigation').getBoundingClientRect();return {old:Math.min(v.height,n.top-r.top),current:Math.min(r.height,n.top-r.top)}})});}fs.writeFileSync('docs/styles/style2/implementation/round1/style1-geometry.json',JSON.stringify(results,null,2));console.log({checks:results.length,changed:results.filter(r=>Math.abs(r.old-r.current)>.1)});if(results.some(r=>Math.abs(r.old-r.current)>.1))process.exitCode=1;await b.close()})();
